  test("invalid durable observation replacement is proof drift for direct and ordinary paths", async () => {
    for (const surface of ["direct-read", "ordinary-delete"] as const) {
      for (const invalidKind of ["oversized", "nonregular"] as const) {
        for (const hookExit of ["return", "throw"] as const) {
          const { tempRoot, workspaceRoot } = await createTempWorkspacePath();
          tempRoots.push(tempRoot);
          const schemaBase = z.object({ id: z.string() });
          let schemaCalls = 0;
          let conditionCalls = 0;
          const schema = schemaBase.superRefine(() => {
            schemaCalls += 1;
          });
          const record = { id: `invalid-repaired-${surface}-${invalidKind}-${hookExit}` };
          const evidenceRef = `invalid.observation.${surface}.${invalidKind}.${hookExit}`;
          const path = workspaceRecordPath(
            workspaceRoot,
            ["invalid-observation", surface, invalidKind, hookExit, "record.json"],
            evidenceRef
          );
          await mkdir(dirname(path), { recursive: true });
          if (invalidKind === "oversized") {
            await writeFile(path, Buffer.alloc(MAX_SERVICE_RECORD_BYTES + 1, 0x61), {
              flag: "wx",
              mode: 0o600
            });
          } else {
            await mkdir(path);
          }
          const displacedPath = `${path}.admitted`;
          const marker = Object.assign(new Error(`invalid observation marker ${invalidKind}`), {
            code: "ENOENT"
          });
          const failure = await captureError(() =>
            runWithWorkspaceRecordPublicationHooks(
              {
                afterDurableRecordObservation: async ({ status }) => {
                  expect(status).toBe("invalid");
                  await rename(path, displacedPath);
                  if (invalidKind === "oversized") {
                    await writeFile(path, Buffer.alloc(MAX_SERVICE_RECORD_BYTES + 1, 0x62), {
                      flag: "wx",
                      mode: 0o600
                    });
                  } else {
                    await mkdir(path);
                  }
                  if (hookExit === "throw") throw marker;
                }
              },
              () => surface === "direct-read"
                ? readJsonRecord(path, evidenceRef, schema)
                : conditionalDeleteJsonRecord(path, evidenceRef, schema, {
                    kind: "record",
                    expected: record,
                    matches: () => {
                      conditionCalls += 1;
                      return true;
                    }
                  })
            )
          );
          expect(findErrorNode(failure, (error) => error instanceof TaskServiceError)).toBeDefined();
          expect((semanticPrimaryError(failure) as TaskServiceError).code).toBe(
            "workspace_path_not_safe"
          );
          expect(errorTreeContains(failure, marker)).toBe(hookExit === "throw");
          expect(
            findErrorNode(
              failure,
              (error) => error instanceof TaskServiceError &&
                error.code === "record_malformed" &&
                error.message === (invalidKind === "oversized"
                  ? "Record exceeds the M1 bounded read size."
                  : "Record path is not a safe regular file.")
            )
          ).toBeInstanceOf(TaskServiceError);
          const provenanceAggregate = findPreservedCompensationAggregate(failure);
          expect(provenanceAggregate).toBeDefined();
          const provenanceErrors = provenanceAggregate!.errors;
          expect(provenanceErrors[0]).toMatchObject({
            code: "record_malformed",
            message: invalidKind === "oversized"
              ? "Record exceeds the M1 bounded read size."
              : "Record path is not a safe regular file."
          });
          if (hookExit === "throw") expect(provenanceErrors[1]).toBe(marker);
          expect(schemaCalls).toBe(0);
          expect(conditionCalls).toBe(0);
          if (invalidKind === "oversized") {
            expect((await stat(path)).size).toBe(MAX_SERVICE_RECORD_BYTES + 1);
          } else {
            expect((await stat(path)).isDirectory()).toBe(true);
          }
          expect((await readdir(dirname(path))).some(isOwnedRecordPath)).toBe(false);

          await rm(path, { recursive: true, force: true });
          await rm(displacedPath, { recursive: true, force: true });
          await writeFile(path, `${JSON.stringify(record, null, 2)}\n`, {
            flag: "wx",
            mode: 0o600
          });
          if (surface === "direct-read") {
            expect(await readJsonRecord(path, `${evidenceRef}.retry`, schemaBase)).toEqual(record);
          } else {
            expect(
              await conditionalDeleteJsonRecord(path, `${evidenceRef}.retry`, schemaBase, {
                kind: "record",
                expected: record,
                matches: (current, expected) => current.id === expected.id
              })
            ).toEqual({ status: "deleted" });
          }
        }
      }
    }
  });

  test("ordinary canonical baselines reject FIFO and socket entries without blocking or mutation", async () => {
    for (const kind of ["fifo", "socket"] as const) {
      const tempRoot = await realpath(await mkdtemp("/tmp/shud-special-canonical-"));
      const workspaceRoot = join(tempRoot, "workspace");
      tempRoots.push(tempRoot);
      const schema = z.object({ id: z.string() });
      const record = { id: `special-canonical-${kind}` };
      const evidenceRef = `special.canonical.${kind}`;
      const directorySegments = ["special-canonical", kind] as const;
      const fileName = "record.json";
      const path = workspaceRecordPath(
        workspaceRoot,
        [...directorySegments, fileName],
        evidenceRef
      );
      await mkdir(dirname(path), { recursive: true });

      const holderGate = createAsyncGate();
      const holderAcquired = createSignal();
      const targetContended = createSignal();
      const holder = captureError(() =>
        runWithWorkspaceRecordPublicationHooks(
          {
            afterAuthorityLeaseAcquired: async ({ operation }) => {
              expect(operation).toBe("read");
              holderAcquired.resolve();
              await holderGate.wait;
            }
          },
          () => readJsonRecord(path, `${evidenceRef}.holder`, schema)
        )
      );
      await Promise.race([
        holderAcquired.promise,
        timeoutAfter(1_000, `${kind} baseline holder did not acquire`)
      ]);

      let authorityCallbacks = 0;
      let temporaryCallbacks = 0;
      const attemptedWrite = captureTaskServiceError(() =>
        runWithWorkspaceRecordPublicationHooks(
          {
            onAuthorityContention: ({ operation }) => {
              expect(operation).toBe("rename");
              targetContended.resolve();
            },
            afterAuthorityLeaseAcquired: () => {
              authorityCallbacks += 1;
            },
            afterTemporaryFileWritten: () => {
              temporaryCallbacks += 1;
            }
          },
          () => writeJsonRecord(
            workspaceRoot,
            directorySegments,
            fileName,
            record,
            evidenceRef,
            schema
          )
        )
      );
      await Promise.race([
        targetContended.promise,
        timeoutAfter(1_000, `${kind} baseline target did not queue`)
      ]);

      let socketServer: Server | undefined;
      if (kind === "fifo") {
        await createFifo(path);
      } else {
        socketServer = createServer();
        await new Promise<void>((resolvePromise, rejectPromise) => {
          const rejectOnError = (error: Error) => rejectPromise(error);
          socketServer!.once("error", rejectOnError);
          socketServer!.listen(path, () => {
            socketServer!.off("error", rejectOnError);
            resolvePromise();
          });
        });
      }

      try {
        const before = await lstat(path, { bigint: true });
        expect(kind === "fifo" ? before.isFIFO() : before.isSocket()).toBe(true);
        holderGate.open();
        const failure = await Promise.race([
          attemptedWrite,
          timeoutAfter(1_500, `${kind} canonical baseline blocked`)
        ]);

        expect(failure.code).toBe("workspace_path_not_safe");
        expect(authorityCallbacks).toBe(0);
        expect(temporaryCallbacks).toBe(0);
        const after = await lstat(path, { bigint: true });
        expect(kind === "fifo" ? after.isFIFO() : after.isSocket()).toBe(true);
        expect(after.dev).toBe(before.dev);
        expect(after.ino).toBe(before.ino);
        expect(after.mode).toBe(before.mode);
        expect(after.nlink).toBe(before.nlink);
        expect((await readdir(dirname(path))).some(isOwnedRecordPath)).toBe(false);
      } finally {
        holderGate.open();
        await Promise.allSettled([holder, attemptedWrite]);
        if (socketServer) await closeServer(socketServer);
      }

      await rm(path, { force: true });
      expect(
        await writeJsonRecord(
          workspaceRoot,
          directorySegments,
          fileName,
          record,
          `${evidenceRef}.retry`,
          schema
        )
      ).toEqual(record);
      expect(await readJsonRecord(path, `${evidenceRef}.retry`, schema)).toEqual(record);
    }
  });

  test("durable parent validators reject callback-time FIFO and socket replacements bounded", async () => {
    for (const kind of ["fifo", "socket"] as const) {
      for (const hookExit of ["return", "throw"] as const) {
        const tempRoot = await realpath(await mkdtemp("/tmp/shud-durable-special-transition-"));
        tempRoots.push(tempRoot);
        const path = join(tempRoot, `${kind}-${hookExit}.json`);
        const displacedPath = `${path}.admitted`;
        const bytes = Buffer.from(`durable ${kind} ${hookExit}\n`);
        await writeFile(path, bytes, { flag: "wx", mode: 0o600 });
        const admitted = await readOwnedFileState(path);
        const marker = new Error(`durable validator ${kind} ${hookExit}`);
        let server: Server | undefined;
        let validatorCalls = 0;

        const result = await Promise.race([
          readDurableSingleLinkFile({
            path,
            maxBytes: MAX_SERVICE_RECORD_BYTES,
            validateParentPath: async () => {
              validatorCalls += 1;
              if (validatorCalls === 1) {
                await replaceRegularPathWithSpecialEntry(
                  path,
                  displacedPath,
                  kind
                );
                server = specialEntryServers.get(path);
                if (hookExit === "throw") throw marker;
              }
              return true;
            }
          }),
          timeoutAfter(1_500, `durable ${kind} ${hookExit} replacement blocked`)
        ]);

        expect(result.status).toBe("invalid");
        if (result.status === "invalid") {
          expect(result.reason).toBe(
            hookExit === "throw"
              ? "parent_not_safe"
              : kind === "fifo"
                ? "not_regular_file"
                : "open_failed"
          );
          expect(result.cause === marker).toBe(hookExit === "throw");
        }
        expect(await readOwnedFileState(displacedPath)).toEqual(admitted);
        const special = await lstat(path, { bigint: true });
        expect(kind === "fifo" ? special.isFIFO() : special.isSocket()).toBe(true);

        if (server) {
          await closeServer(server);
          await Bun.sleep(10);
        }
        await removeEntryIfPresent(path);
        await rename(displacedPath, path);
        const repaired = await readDurableSingleLinkFile({
          path,
          maxBytes: MAX_SERVICE_RECORD_BYTES,
          validateParentPath: () => true
        });
        expect(repaired.status).toBe("read");
        if (repaired.status === "read") expect(repaired.bytes).toEqual(bytes);
      }
    }
  });

