  test("task-lane empty removal uses direct rmdir without enumerating lane entries", async () => {
    const sourcePath = join(import.meta.dir, "workspace-record-store.ts");
    const sourceText = await readFile(sourcePath, "utf8");
    const sourceFile = ts.createSourceFile(
      sourcePath,
      sourceText,
      ts.ScriptTarget.Latest,
      true,
      ts.ScriptKind.TS
    );
    let removalFunction: ts.FunctionDeclaration | undefined;
    const findRemovalFunction = (node: ts.Node): void => {
      if (
        ts.isFunctionDeclaration(node) &&
        node.name?.text === "removeWorkspaceRecordDirectoryIfEmpty"
      ) {
        removalFunction = node;
        return;
      }
      ts.forEachChild(node, findRemovalFunction);
    };
    findRemovalFunction(sourceFile);
    expect(removalFunction).toBeDefined();
    const calledFunctions: string[] = [];
    const collectCalls = (node: ts.Node): void => {
      if (ts.isCallExpression(node)) {
        if (ts.isIdentifier(node.expression)) {
          calledFunctions.push(node.expression.text);
        } else if (ts.isPropertyAccessExpression(node.expression)) {
          calledFunctions.push(node.expression.name.text);
        }
      }
      ts.forEachChild(node, collectCalls);
    };
    collectCalls(removalFunction!.body!);
    expect(calledFunctions.filter((name) => name === "readdir")).toEqual([]);
    expect(calledFunctions.filter((name) => name === "rmdir")).toEqual(["rmdir"]);
    const removalBody = removalFunction!.body!.getText(sourceFile);
    const caughtErrorCodes = [...removalBody.matchAll(/hasErrorCode\(error,\s*"([A-Z]+)"\)/g)]
      .map((match) => match[1]);
    expect(caughtErrorCodes).toEqual(["ENOTEMPTY", "EEXIST"]);

    const { tempRoot, workspaceRoot } = await createTempWorkspacePath();
    tempRoots.push(tempRoot);
    expect(
      await removeWorkspaceRecordDirectoryIfEmpty(
        workspaceRoot,
        ["tasks", "TASK-direct-rmdir-missing"],
        "strategy-12.rmdir.missing"
      )
    ).toEqual({ status: "missing" });

    const emptyLane = join(workspaceRoot, "tasks", "TASK-direct-rmdir-empty");
    await mkdir(emptyLane, { recursive: true });
    expect(
      await removeWorkspaceRecordDirectoryIfEmpty(
        workspaceRoot,
        ["tasks", "TASK-direct-rmdir-empty"],
        "strategy-12.rmdir.empty"
      )
    ).toEqual({ status: "removed" });
    await expectPathMissing(emptyLane);

    const occupiedLane = join(workspaceRoot, "tasks", "TASK-direct-rmdir-occupied");
    const sentinelPath = join(occupiedLane, "sentinel.txt");
    await mkdir(occupiedLane, { recursive: true });
    await writeFile(sentinelPath, "preserve direct-rmdir sentinel", { flag: "wx" });
    expect(
      await removeWorkspaceRecordDirectoryIfEmpty(
        workspaceRoot,
        ["tasks", "TASK-direct-rmdir-occupied"],
        "strategy-12.rmdir.occupied"
      )
    ).toEqual({ status: "not_empty" });
    expect(await readFile(sentinelPath, "utf8")).toBe("preserve direct-rmdir sentinel");

    const deniedParent = join(workspaceRoot, "direct-rmdir-denied-parent");
    const deniedLane = join(deniedParent, "lane");
    await mkdir(deniedLane, { recursive: true });
    await chmod(deniedParent, 0o500);
    let deniedFailure: unknown;
    try {
      deniedFailure = await captureError(() =>
        removeWorkspaceRecordDirectoryIfEmpty(
          workspaceRoot,
          ["direct-rmdir-denied-parent", "lane"],
          "strategy-12.rmdir.denied"
        )
      );
    } finally {
      await chmod(deniedParent, 0o700);
    }
    const deniedCode =
      typeof deniedFailure === "object" &&
      deniedFailure !== null &&
      "code" in deniedFailure
        ? (deniedFailure as NodeJS.ErrnoException).code
        : undefined;
    expect(["EACCES", "EPERM"]).toContain(deniedCode);
    expect((await lstat(deniedLane)).isDirectory()).toBe(true);
  });

  test("S27-P62-01 completed consumption lease linearizes before retained fail intent", async () => {
    const { tempRoot, workspaceRoot } = await createTempWorkspacePath();
    tempRoots.push(tempRoot);
    const rawKey = "task:create:r28-consumption-lease";
    const requestDigest = "digest-r28-consumption-lease";
    const resultRef = "TASK-r28-consumption-lease";
    const service = createIdempotencyRecordService({ workspaceRoot });
    await service.beginRecord({ scope: "task", key: rawKey, requestDigest });
    await service.completeRecord({
      scope: "task",
      key: rawKey,
      requestDigest,
      resultRef
    });
    const recordPath = join(
      workspaceRoot,
      "tasks",
      "_idempotency",
      "task",
      idempotencyRecordFileName(rawKey)
    );
    const consumeEntered = createSignal();
    const consumeGate = createAsyncGate();
    const writeFailure = new Error("S27-P62-01 retained fail-intent write failure");
    const consumeCompletedRecord = (
      service as IdempotencyRecordService & {
        consumeCompletedRecord: (
          input: { scope: "task"; key: string; requestDigest: string },
          consume: (record: IdempotencyRecord & { result_ref: string }) => Promise<unknown>
        ) => Promise<{
          status: string;
          value?: string;
        }>;
      }
    ).consumeCompletedRecord;

    const consumption = consumeCompletedRecord(
      { scope: "task", key: rawKey, requestDigest },
      async (record) => {
        expect(record.result_ref).toBe(resultRef);
        consumeEntered.resolve();
        await consumeGate.wait;
        return { status: "accepted", value: record.result_ref };
      }
    );
    await Promise.race([
      consumeEntered.promise,
      timeoutAfter(1_000, "completed consumer did not acquire its transition lease")
    ]);

    let invalidationSettled = false;
    const invalidation = runWithWorkspaceRecordPublicationHooks(
      {
        afterTemporaryFileWritten: ({ canonicalPath }) => {
          if (canonicalPath === recordPath) throw writeFailure;
        }
      },
      () =>
        service.invalidateCompletedRecord({
          scope: "task",
          key: rawKey,
          requestDigest,
          resultRef
        })
    ).finally(() => {
      invalidationSettled = true;
    });
    invalidation.catch(() => undefined);
    await new Promise((resolvePromise) => setTimeout(resolvePromise, 40));
    expect(invalidationSettled).toBe(false);

    consumeGate.open();
    const consumed = await consumption;
    expect(consumed).toMatchObject({ status: "accepted", value: resultRef });
    if ("mutationAuthority" in consumed) {
      await service.cancelCompletedRecordMutationAuthority(
        consumed.mutationAuthority as never
      );
    }
    expect(await captureThrownValue(() => invalidation)).toBeDefined();

    let laterCallbackCalls = 0;
    const later = await consumeCompletedRecord(
      { scope: "task", key: rawKey, requestDigest },
      async () => {
        laterCallbackCalls += 1;
        return { status: "accepted", value: "unexpected" };
      }
    );
    expect(laterCallbackCalls).toBe(1);
    expect(later.status).toBe("accepted");
    if ("mutationAuthority" in later) {
      await service.cancelCompletedRecordMutationAuthority(later.mutationAuthority);
    }
  });

