async function chmodIncludingSpecialBits(path: string, mode: number): Promise<void> {
  const process = Bun.spawn(["chmod", mode.toString(8), path], {
    stdout: "pipe",
    stderr: "pipe"
  });
  const [exitCode, stderr] = await Promise.all([
    process.exited,
    new Response(process.stderr).text()
  ]);
  if (exitCode !== 0) {
    throw new Error(`chmod failed with exit ${exitCode}: ${stderr.trim()}`);
  }
}

async function createBaseWriterFilesInIsolatedProcess(
  files: readonly Readonly<{ path: string; bytes: Buffer }>[],
  mask: number
): Promise<void> {
  const encodedFiles = files.map((file) => ({
    path: file.path,
    bytes: file.bytes.toString("base64")
  }));
  const script = [
    'const { writeFileSync } = require("node:fs");',
    "const files = JSON.parse(process.argv[1]);",
    "process.umask(Number.parseInt(process.argv[2], 8));",
    'for (const file of files) writeFileSync(file.path, Buffer.from(file.bytes, "base64"), { flag: "wx" });'
  ].join(" ");
  const child = Bun.spawn(
    [process.execPath, "-e", script, JSON.stringify(encodedFiles), mask.toString(8)],
    { stdout: "pipe", stderr: "pipe" }
  );
  const [exitCode, stdout, stderr] = await Promise.all([
    child.exited,
    new Response(child.stdout).text(),
    new Response(child.stderr).text()
  ]);
  if (exitCode !== 0) {
    throw new Error(
      `isolated base writer failed with exit ${exitCode}: ${stderr.trim()} ${stdout.trim()}`.trim()
    );
  }
}

async function runBoundedBunProbe(
  script: string,
  timeoutMs: number
): Promise<Readonly<{
  timedOut: boolean;
  exitCode: number | null;
  stdout: string;
  stderr: string;
}>> {
  const child = Bun.spawn([process.execPath, "-e", script], {
    cwd: resolve(import.meta.dir, "../../../../.."),
    stdout: "pipe",
    stderr: "pipe"
  });
  let timer: ReturnType<typeof setTimeout> | undefined;
  const outcome = await Promise.race([
    child.exited.then((exitCode) => ({ timedOut: false as const, exitCode })),
    new Promise<{ timedOut: true; exitCode: null }>((resolveTimeout) => {
      timer = setTimeout(
        () => resolveTimeout({ timedOut: true, exitCode: null }),
        timeoutMs
      );
    })
  ]);
  if (timer) clearTimeout(timer);
  if (outcome.timedOut) {
    child.kill(9);
    await child.exited;
  }
  const [stdout, stderr] = await Promise.all([
    new Response(child.stdout).text(),
    new Response(child.stderr).text()
  ]);
  return Object.freeze({ ...outcome, stdout, stderr });
}

async function createFifo(path: string): Promise<void> {
  const process = Bun.spawn(["mkfifo", path], {
    stdout: "pipe",
    stderr: "pipe"
  });
  const [exitCode, stderr] = await Promise.all([
    process.exited,
    new Response(process.stderr).text()
  ]);
  if (exitCode !== 0) {
    throw new Error(`mkfifo failed with exit ${exitCode}: ${stderr.trim()}`);
  }
}

async function replaceRegularPathWithSpecialEntry(
  path: string,
  displacedPath: string,
  kind: "fifo" | "socket"
): Promise<void> {
  await rename(path, displacedPath);
  if (kind === "fifo") {
    await createFifo(path);
    return;
  }
  const server = createServer();
  await new Promise<void>((resolvePromise, rejectPromise) => {
    const rejectOnError = (error: Error) => rejectPromise(error);
    server.once("error", rejectOnError);
    server.listen(path, () => {
      server.off("error", rejectOnError);
      resolvePromise();
    });
  });
  specialEntryServers.set(path, server);
}

async function removeEntryIfPresent(path: string): Promise<void> {
  try {
    await unlink(path);
  } catch (error) {
    if (!hasTestErrorCode(error, "ENOENT") && !hasTestErrorCode(error, "ENOTDIR")) {
      throw error;
    }
  }
}

async function closeServer(server: Server): Promise<void> {
  const address = server.address();
  await new Promise<void>((resolvePromise, rejectPromise) => {
    server.close((error) => {
      if (error && !hasTestErrorCode(error, "ENOENT") && !hasTestErrorCode(error, "ENOTDIR")) {
        rejectPromise(error);
      }
      else resolvePromise();
    });
  });
  if (typeof address === "string") specialEntryServers.delete(address);
}

function hasTestErrorCode(error: unknown, code: string): boolean {
  return (
    typeof error === "object" &&
    error !== null &&
    "code" in error &&
    (error as { code?: unknown }).code === code
  );
}

class StructuredServiceError extends Error {
  readonly code: string;
  readonly details: Readonly<{ surface: string; immutability: string }>;

  constructor(
    message: string,
    code: string,
    details: Readonly<{ surface: string; immutability: string }>,
    cause: unknown
  ) {
    super(message, { cause });
    this.name = "StructuredServiceError";
    Object.defineProperty(this, "code", {
      configurable: false,
      enumerable: true,
      writable: false,
      value: code
    });
    Object.defineProperty(this, "details", {
      configurable: false,
      enumerable: false,
      writable: false,
      value: details
    });
  }
}

async function captureError(action: () => Promise<unknown>): Promise<Error> {
  try {
    await action();
  } catch (error) {
    expect(error).toBeInstanceOf(Error);
    return error as Error;
  }

  throw new Error("Expected an error.");
}

async function captureThrownValue(action: () => Promise<unknown>): Promise<unknown> {
  try {
    await action();
  } catch (error) {
    return error;
  }
  throw new Error("Expected a thrown value.");
}

function expectPreservedOwnDescriptors(
  error: Error,
  expected: Record<PropertyKey, PropertyDescriptor>
): void {
  const actual = Object.getOwnPropertyDescriptors(error);
  expect(Reflect.ownKeys(actual)).toEqual(Reflect.ownKeys(expected));
  for (const key of Reflect.ownKeys(expected)) {
    const expectedDescriptor = expected[key]!;
    const actualDescriptor = actual[key]!;
    if (key === "cause") {
      expect({ ...actualDescriptor, value: undefined }).toEqual({
        ...expectedDescriptor,
        value: undefined
      });
    } else {
      expect(actualDescriptor).toEqual(expectedDescriptor);
    }
  }
}

async function captureTaskServiceError(action: () => Promise<unknown>): Promise<TaskServiceError> {
  try {
    await action();
  } catch (error) {
    const taskServiceError = taskServiceErrorAtBoundary(error);
    expect(taskServiceError).toBeDefined();
    return taskServiceError!;
  }

  throw new Error("Expected TaskServiceError.");
}

async function expectFileDescriptorClosed(fd: number): Promise<void> {
  const error = await captureError(
    () =>
      new Promise<void>((resolvePromise, rejectPromise) => {
        fstat(fd, (statError) => {
          if (statError) rejectPromise(statError);
          else resolvePromise();
        });
      })
  );
  expect(error).toMatchObject({ code: "EBADF" });
}

async function readFileDescriptorIdentity(
  fd: number
): Promise<{ dev: bigint; ino: bigint }> {
  const entry = await new Promise<BigIntStats>(
    (resolvePromise, rejectPromise) => {
      fstat(fd, { bigint: true }, (statError, descriptorStat) => {
        if (statError) rejectPromise(statError);
        else resolvePromise(descriptorStat);
      });
    }
  );
  return { dev: entry.dev, ino: entry.ino };
}

function findOpenFileDescriptorsByIdentity(identity: {
  dev: bigint;
  ino: bigint;
}): number[] {
  const matches: number[] = [];
  for (let fd = 3; fd <= 2048; fd += 1) {
    try {
      const entry = fstatSync(fd, { bigint: true });
      if (entry.dev === identity.dev && entry.ino === identity.ino) {
        matches.push(fd);
      }
    } catch {
      // Unopened descriptor slots reject the fstat probe; skip them.
    }
  }
  return matches;
}

function findPreservedCompensationAggregate(value: unknown): AggregateError | undefined {
  if (failureLedger(value)) {
    const compensations = orderedDistinctCompensationFailures(value).filter(
      (entry) => failureLedger(entry) === undefined
    );
    return compensations.length === 0
      ? undefined
      : new AggregateError(compensations, "Failure occurrence ledger compatibility view");
  }
  const envelope = findErrorNode(
    value,
    (error) => error instanceof PreservedErrorCompensationEnvelope
  ) as PreservedErrorCompensationEnvelope | undefined;
  return envelope?.cause instanceof AggregateError ? envelope.cause : undefined;
}

function knownPreservedCompensationAggregate(value: unknown): AggregateError {
  if (failureLedger(value)) {
    return new AggregateError(
      orderedDistinctCompensationFailures(value).filter(
        (entry) => failureLedger(entry) === undefined
      ),
      "Failure occurrence ledger compatibility view"
    );
  }
  const envelope = value instanceof PreservedErrorCompensationEnvelope
    ? value
    : value instanceof TaskServiceError &&
        value.cause instanceof PreservedErrorCompensationEnvelope
      ? value.cause
      : undefined;
  expect(envelope).toBeDefined();
  expect(envelope!.cause).toBeInstanceOf(AggregateError);
  return envelope!.cause as AggregateError;
}

function nonCarrierFailureEvents(value: unknown) {
  return failureEvents(value).filter(
    (event) => failureLedger(event.value) === undefined
  );
}

function aggregateErrorMessages(value: unknown, ancestors = new Set<unknown>()): string[] {
  if (failureLedger(value)) {
    const orderedValues = [
      ...failureEvents(value).map((event) => event.value),
      ...failureGraphNodes(value).map((node) => node.value)
    ];
    const seen = new Set<unknown>();
    return orderedValues.flatMap((entry) => {
      if (seen.has(entry)) return [];
      seen.add(entry);
      return entry instanceof Error ? [entry.message] : [];
    });
  }
  if (!(value instanceof Error) || ancestors.has(value)) return [];
  ancestors.add(value);
  const semanticPrimary = semanticPrimaryError(value);
  const messages = semanticPrimary && semanticPrimary !== value ? [] : [value.message];
  if (semanticPrimary && semanticPrimary !== value) {
    messages.push(...aggregateErrorMessages(semanticPrimary, ancestors));
  }
  if (value instanceof AggregateError) {
    for (const error of value.errors) {
      messages.push(...aggregateErrorMessages(error, ancestors));
    }
  }
  messages.push(...aggregateErrorMessages(value.cause, ancestors));
  return messages;
}

function errorTreeContains(
  value: unknown,
  expected: unknown,
  ancestors = new Set<unknown>()
): boolean {
  if (failureLedger(value)) {
    return failureEvents(value).some((entry) => Object.is(entry.value, expected)) ||
      failureGraphNodes(value).some((node) => Object.is(node.value, expected));
  }
  if (value === expected) return true;
  if (!(value instanceof Error) || ancestors.has(value)) return false;
  ancestors.add(value);
  if (value instanceof AggregateError) {
    for (const error of value.errors) {
      if (errorTreeContains(error, expected, ancestors)) return true;
    }
  }
  const semanticPrimary = semanticPrimaryError(value);
  if (
    semanticPrimary &&
    semanticPrimary !== value &&
    errorTreeContains(semanticPrimary, expected, ancestors)
  ) {
    return true;
  }
  return errorTreeContains(value.cause, expected, ancestors);
}

function countErrorGraphIdentity(
  value: unknown,
  expected: unknown,
  ancestors = new Set<unknown>()
): number {
  if (failureLedger(value)) {
    return orderedDistinctFailures(value).filter((entry) => Object.is(entry, expected)).length;
  }
  if (value === expected) return 1;
  if (!(value instanceof Error) || ancestors.has(value)) return 0;
  const nextAncestors = new Set(ancestors);
  nextAncestors.add(value);
  let count = 0;
  if (value instanceof AggregateError) {
    for (const error of value.errors) {
      count += countErrorGraphIdentity(error, expected, nextAncestors);
    }
  }
  const semanticPrimary = semanticPrimaryError(value);
  if (semanticPrimary && semanticPrimary !== value) {
    count += countErrorGraphIdentity(semanticPrimary, expected, nextAncestors);
  }
  count += countErrorGraphIdentity(value.cause, expected, nextAncestors);
  return count;
}

function findErrorNode(
  value: unknown,
  predicate: (error: Error) => boolean,
  ancestors = new Set<unknown>()
): Error | undefined {
  if (failureLedger(value)) {
    const candidates = [
      value,
      ...(value instanceof PreservedErrorCompensationEnvelope && value.cause instanceof Error
        ? [value.cause]
        : []),
      ...failureEvents(value).map((event) => event.value),
      ...failureGraphNodes(value).map((node) => node.value)
    ];
    for (const candidate of candidates) {
      const taskServiceError = taskServiceErrorAtBoundary(candidate);
      if (taskServiceError && predicate(taskServiceError)) return taskServiceError;
      if (taskServiceError?.cause !== undefined) {
        const nested = findErrorNode(taskServiceError.cause, predicate, ancestors);
        if (nested) return nested;
      }
      if (candidate instanceof Error && predicate(candidate)) return candidate;
      if (candidate instanceof Error && candidate.cause !== undefined) {
        const nested = findErrorNode(candidate.cause, predicate, ancestors);
        if (nested) return nested;
      }
    }
    return undefined;
  }
  if (!(value instanceof Error) || ancestors.has(value)) return undefined;
  ancestors.add(value);
  const semanticPrimary = semanticPrimaryError(value);
  if (semanticPrimary && semanticPrimary !== value) {
    const found = findErrorNode(semanticPrimary, predicate, ancestors);
    if (found) return found;
  }
  if (predicate(value)) return value;
  if (value instanceof AggregateError) {
    for (const error of value.errors) {
      const found = findErrorNode(error, predicate, ancestors);
      if (found) return found;
    }
  }
  return findErrorNode(value.cause, predicate, ancestors);
}

function countErrorNodes(
  value: unknown,
  predicate: (error: Error) => boolean,
  ancestors = new Set<unknown>()
): number {
  if (failureLedger(value)) {
    const candidates = [
      value,
      ...(value instanceof PreservedErrorCompensationEnvelope && value.cause instanceof Error
        ? [value.cause]
        : []),
      ...failureEvents(value).map((event) => event.value),
      ...failureGraphNodes(value).map((node) => node.value)
    ];
    return [...new Set(candidates)].filter(
      (candidate) => candidate instanceof Error && predicate(candidate)
    ).length;
  }
  if (!(value instanceof Error) || ancestors.has(value)) return 0;
  ancestors.add(value);
  const semanticPrimary = semanticPrimaryError(value);
  let count = semanticPrimary && semanticPrimary !== value ? 0 : predicate(value) ? 1 : 0;
  if (semanticPrimary && semanticPrimary !== value) {
    count += countErrorNodes(semanticPrimary, predicate, ancestors);
  }
  if (value instanceof AggregateError) {
    for (const error of value.errors) {
      count += countErrorNodes(error, predicate, ancestors);
    }
  }
  return count + countErrorNodes(value.cause, predicate, ancestors);
}

async function captureConditionalDeleteError(
  action: () => Promise<unknown>
): Promise<WorkspaceRecordConditionalDeleteError> {
  try {
    await action();
  } catch (error) {
    expect(error).toBeInstanceOf(WorkspaceRecordConditionalDeleteError);
    return error as WorkspaceRecordConditionalDeleteError;
  }
  throw new Error("Expected WorkspaceRecordConditionalDeleteError.");
}

function isOwnedRecordPath(name: string): boolean {
  return name.endsWith(".authority") || name.endsWith(".tmp");
}

async function findOnlyAuthorityNamespace(directoryPath: string): Promise<string> {
  const authorityNames = (await readdir(directoryPath)).filter((name) =>
    name.endsWith(".authority")
  );
  expect(authorityNames).toHaveLength(1);
  return join(directoryPath, authorityNames[0]!);
}

async function expectPrivateAuthorityDirectory(path: string): Promise<void> {
  const entry = await lstat(path);
  expect(entry.isDirectory()).toBe(true);
  expect(entry.isSymbolicLink()).toBe(false);
  expect(entry.mode & 0o7777).toBe(0o700);
}

async function captureWorkspacePathSafetyError(
  action: () => Promise<unknown>
): Promise<WorkspacePathSafetyError> {
  try {
    await action();
  } catch (error) {
    expect(error).toBeInstanceOf(WorkspacePathSafetyError);
    return error as WorkspacePathSafetyError;
  }

  throw new Error("Expected WorkspacePathSafetyError.");
}

function expectErrorNotToLeakRecordContent(error: TaskServiceError, content: string): void {
  const cause = (error as Error & { cause?: unknown }).cause;
  const exposedError = JSON.stringify({
    message: error.message,
    userMessage: error.userMessage,
    evidenceRefs: error.evidenceRefs,
    recommendedNextActions: error.recommendedNextActions,
    causeMessage: cause instanceof Error ? cause.message : cause
  });
  expect(exposedError).not.toContain(content);
}

async function expectPathMissing(path: string): Promise<void> {
  try {
    await access(path);
  } catch {
    return;
  }

  throw new Error(`Expected path to be missing: ${path}`);
}

function idempotencyTransitionGuardPath(workspaceRoot: string, key: string): string {
  return join(
    workspaceRoot,
    "tasks",
    "_idempotency",
    "task",
    `${sha256Hex(`transition:${key}`)}.guard.json`
  );
}

function idempotencyTransitionCleanupLockPath(workspaceRoot: string, key: string): string {
  return join(
    workspaceRoot,
    "tasks",
    "_idempotency",
    "task",
    `${sha256Hex(`transition-cleanup:${key}`)}.guard-cleanup`
  );
}

function isAuthorityNamespaceForCanonicalPath(
  namespacePath: string,
  canonicalPath: string
): boolean {
  const namespaceName = basename(namespacePath);
  return (
    dirname(namespacePath) === dirname(canonicalPath) &&
    namespaceName.startsWith(`.${basename(canonicalPath)}-`) &&
    namespaceName.endsWith(".authority")
  );
}

function createPostMutationNamespaceFailureHooks(
  failures: ReadonlyMap<string, unknown>
): Readonly<{
  publicationHooks: WorkspaceRecordPublicationHooks;
  compensationHooks: Parameters<typeof runWithWorkspaceRecordCompensationTestHooks>[0];
  conditionalDeletePaths: string[];
}> {
  const producerNamespaces = new Set<string>();
  const conditionalDeletePaths: string[] = [];
  const failureForNamespace = (namespacePath: string): unknown | undefined => {
    if (producerNamespaces.has(namespacePath)) return undefined;
    for (const [canonicalPath, failure] of failures) {
      if (isAuthorityNamespaceForCanonicalPath(namespacePath, canonicalPath)) return failure;
    }
    return undefined;
  };
  return {
    publicationHooks: {
      afterCanonicalLink: ({ temporaryPath }) => {
        producerNamespaces.add(dirname(temporaryPath));
      },
      beforeConditionalDelete: ({ path }) => {
        conditionalDeletePaths.push(path);
      },
      beforeAuthorityNamespaceRemoval: ({ path }) => {
        const failure = failureForNamespace(path);
        if (failure !== undefined) throw failure;
      }
    },
    compensationHooks: {
      beforeTerminalAuthorityNamespaceRemovalSyscall: ({ path }) => {
        const failure = failureForNamespace(path);
        if (failure !== undefined) throw failure;
      }
    },
    conditionalDeletePaths
  };
}

function createCleanupPermitCloseTracker(paths: readonly string[]): Readonly<{
  record: (input: Readonly<{ path: string; fd: number }>) => void;
  waitForAll: () => Promise<void>;
  count: (path: string) => number;
  descriptors: (path: string) => readonly number[];
}> {
  const trackedPaths = new Set(paths);
  const closeSignals = new Map(paths.map((path) => [path, createSignal()]));
  const closeCounts = new Map(paths.map((path) => [path, 0]));
  const closedDescriptors = new Map(paths.map((path) => [path, [] as number[]]));
  return {
    record: ({ path, fd }) => {
      if (!trackedPaths.has(path)) return;
      closeCounts.set(path, (closeCounts.get(path) ?? 0) + 1);
      closedDescriptors.get(path)!.push(fd);
      closeSignals.get(path)!.resolve();
    },
    waitForAll: async () => {
      await Promise.all([...closeSignals.values()].map((signal) => signal.promise));
    },
    count: (path) => closeCounts.get(path) ?? 0,
    descriptors: (path) => closedDescriptors.get(path) ?? []
  };
}

async function delay(milliseconds: number): Promise<void> {
  await new Promise<void>((resolvePromise) => setTimeout(resolvePromise, milliseconds));
}

async function moveDirectoryAwayAndBack(directoryPath: string): Promise<void> {
  const displacedPath = `${directoryPath}.same-inode-parent-aba`;
  const before = await lstat(directoryPath, { bigint: true });
  await rename(directoryPath, displacedPath);
  await delay(2);
  await rename(displacedPath, directoryPath);
  const after = await lstat(directoryPath, { bigint: true });
  expect(after.dev).toBe(before.dev);
  expect(after.ino).toBe(before.ino);
  expect(after.ctimeNs !== before.ctimeNs || after.mtimeNs !== before.mtimeNs).toBe(true);
}

async function applyExternalParentMetadataDrift(
  directoryPath: string,
  drift: "sibling-only" | "aba-only" | "aba-and-sibling"
): Promise<void> {
  if (drift === "aba-only" || drift === "aba-and-sibling") {
    await moveDirectoryAwayAndBack(directoryPath);
  }
  if (drift === "aba-only") return;

  const before = await lstat(directoryPath, { bigint: true });
  const siblingPath = join(directoryPath, ".direct-external-sibling-drift");
  for (let attempt = 1; attempt <= 8; attempt += 1) {
    await delay(2);
    await writeFile(siblingPath, `external sibling drift ${attempt}\n`, {
      flag: "wx",
      mode: 0o600
    });
    await delay(2);
    await unlink(siblingPath);
    const after = await lstat(directoryPath, { bigint: true });
    expect(after.dev).toBe(before.dev);
    expect(after.ino).toBe(before.ino);
    if (after.mtimeNs !== before.mtimeNs) return;
  }

  throw new Error("Direct sibling create/delete did not advance parent mtime.");
}

async function timeoutAfter(milliseconds: number, message: string): Promise<never> {
  await new Promise((resolve) => setTimeout(resolve, milliseconds));
  throw new Error(message);
}

